import { isValidObjectId } from "mongoose";
import { Booking } from "../../Models/booking.model.js";

export const addBooking = async (req, res) => {
  try {
    const { fair_id, from, to, customer, driver, vehicle, booking_start_date, booking_end_date } = req.body;
    if (!from) {
      return res.status(404).json({
        message: "Enter Name",
        success: false
      })
    } else if (!to) {
      return res.status(404).json({
        message: "Enter Mobile No.",
        success: false
      })
    } else if (!customer) {
      return res.status(404).json({
        message: "Enter Age ",
        success: false
      })
    } else if (!driver) {
      return res.status(404).json({
        message: "Enter Licence No.",
        success: false
      })
    } else if (!vehicle) {
      return res.status(404).json({
        message: "Enter Experience.",
        success: false
      })
    }
    else if (!booking_start_date) {
      return res.status(404).json({
        message: "Enter Experience.",
        success: false
      })
    }
    else if (!booking_end_date) {
      return res.status(404).json({
        message: "Enter Experience.",
        success: false
      })
    }
    const data = {
      fair_id, from, to, customer, driver, vehicle, booking_start_date, booking_end_date
    }
    const response = new Booking(data);
    await response.save();
    return res.status(200).json({
      message: "Booking successfully",
      success: true,
      data: response
    })
  } catch (error) {
    console.log(error)
    return res.status(404).json({
      message: "Error while Booking",
      success: false,
      error: error.message
    })
  }
}


export const viewBooking = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const operation = await Booking.findById(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in DB",
        success: false
      })
    }
    return res.status(200).json({
      message: "Fetching data successfully",
      success: true,
      data: operation
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while fetching data",
      success: false,
      error: error.message
    })
  }
}


